\begin{theorem}[Even logarithmic Brunn--Minkowski inequality]
\label{thm:main}
Let $n\ge1$ and let $K,L\subset\R^n$ be convex bodies satisfying
$K=-K$ and $L=-L$. For every $0\le\lambda\le1$,
\begin{equation}\label{eq:main}
 \left|\mathcal W[h_K^{1-\lambda}h_L^\lambda]\right|
 \ge |K|^{1-\lambda}|L|^\lambda.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There is a fixed subset $S$ of real $\ell_2$, equipped with its induced Hilbert distance, whose doubling constant is at most $76800$ and which admits no bi-Lipschitz embedding into $\R^k$ for any positive integer $k$, at any finite distortion.
\end{theorem}

